#include "helper.hpp"
int main(){vector<int>a(5);int k=0;for(int i=0;i<5;i++)for(int j=i+1;j<5;j++,k++){if(759>>k&1)a[i]|=1<<j;else a[j]|=1<<i;}a=ear(a,2);for(int pm:{50,24}){auto b=ear(a,pm);int n=b.size(),h=hp(b);for(int j:{1,2}){int target=3*h+2*j; bool done=false;long long candidates=0; for(int u=0;u<(1<<n)&&!done;u++){auto c=ear(b,u);if(hp(c)>target)continue;for(int v=0;v<(1<<n)&&!done;v++){auto d=ear(c,v);int h2=hp(d);if(h2>target)continue;candidates++;int N=n+2, ones[9], inter[9][9];for(int i=0;i<N;i++)ones[i]=hp(ear(d,1<<i))-h2;for(int i=0;i<N;i++)for(int k=i+1;k<N;k++)inter[i][k]=hp(ear(d,(1<<i)|(1<<k)))-h2-ones[i]-ones[k];for(int w=0;w<(1<<N);w++){int z=h2;for(int i=0;i<N;i++)if(w>>i&1){z+=ones[i];for(int k=i+1;k<N;k++)if(w>>k&1)z+=inter[i][k];}if(z==target){cout<<"h="<<h<<" target="<<target<<" masks="<<u<<","<<v<<","<<w<<" h2="<<h2<<" candidates="<<candidates<<endl;done=true;break;}}}}if(!done)cout<<"h="<<h<<" target="<<target<<" no result, candidates="<<candidates<<endl;}}}
